package ma.enset.smartdevcollab.service;
import ma.enset.smartdevcollab.dto.AiDtos.*; import ma.enset.smartdevcollab.dto.TaskDtos.*; import ma.enset.smartdevcollab.entity.*; import ma.enset.smartdevcollab.repository.UserRepository; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.*;
@Service public class AiService{ private final UserRepository users; private final TaskService taskService; public AiService(UserRepository users,TaskService taskService){this.users=users;this.taskService=taskService;}
 public AiProjectPlanResponse generate(AiProjectRequest r){ List<User> us=users.findAll(); String text=(r.cahierDesCharges()+" "+r.projectTitle()).toLowerCase(); List<String> base=new ArrayList<>(); base.add("Analyse du cahier des charges"); base.add("Conception UML et base de donnees"); if(text.contains("react")||text.contains("frontend")||text.contains("interface")) base.add("Developpement interface React"); if(text.contains("spring")||text.contains("backend")||text.contains("api")) base.add("Developpement API REST Spring Boot"); if(text.contains("mysql")||text.contains("base")) base.add("Creation schema MySQL et repositories JPA"); base.add("Integration authentification JWT"); base.add("Tableau Kanban et collaboration"); base.add("Tests, documentation et presentation"); List<AiTaskSuggestion> tasks=new ArrayList<>(); int i=0; for(String title:base){ User u=match(us,title); String pr=(i<3?"HIGH": i<6?"MEDIUM":"LOW"); tasks.add(new AiTaskSuggestion(title, desc(title), pr, u==null?null:u.getEmail(), u==null?"Non assigne":u.getFullName(), livrable(title), LocalDate.now().plusDays(2+i))); i++; } return new AiProjectPlanResponse("Plan WBS genere automatiquement avec assignation selon les competences declarees.", tasks); }
 private String desc(String title){ return "Realiser: "+title+". Verifier, documenter et valider avec l'equipe."; } private String livrable(String title){ return title.contains("base")||title.contains("MySQL")?"Script SQL + modele JPA": title.contains("React")?"Pages React fonctionnelles": title.contains("API")?"Endpoints REST testes": title.contains("Tests")?"Rapport + captures": "Document ou fonctionnalite validee"; }
 private User match(List<User> users,String task){ String t=task.toLowerCase(); User best=null; int score=-1; for(User u:users){ String s=((u.getSkillsText()==null?"":u.getSkillsText())+" "+u.getFullName()).toLowerCase(); int sc=0; if(t.contains("react")||t.contains("interface")){ if(s.contains("react")||s.contains("front")||s.contains("ui")) sc+=5; } if(t.contains("spring")||t.contains("api")||t.contains("jwt")){ if(s.contains("spring")||s.contains("backend")||s.contains("java")) sc+=5; } if(t.contains("mysql")||t.contains("base")){ if(s.contains("mysql")||s.contains("bdd")||s.contains("database")) sc+=5; } if(t.contains("test")||t.contains("documentation")){ if(s.contains("test")||s.contains("doc")) sc+=5; } if(sc>score){score=sc; best=u;} } return best; }
 public List<?> createTasks(CreateTasksFromAiRequest r){ List<Object> created=new ArrayList<>(); for(AiTaskSuggestion s:r.tasks()){ Long userId=null; if(s.assignedToEmail()!=null) userId=users.findByEmail(s.assignedToEmail()).map(User::getId).orElse(null); created.add(taskService.create(new TaskRequest(s.title(),s.description(),TaskStatus.TODO,Priority.valueOf(s.priority()),r.projectId(),userId,s.dueDate(),s.deliverable()))); } return created; }
}
